@Service
public class ProductCacheService {
    @Autowired private RedisTemplate<String, Product> redis;
    @Autowired private ProductRepository db;

    public Product getProduct(String id) {
        // BUG: Standard naive Cache-Aside prone to thundering herd upon TTL expiry
        Product cached = redis.opsForValue().get("product:" + id);
        if (cached == null) {
            cached = db.findById(id).orElseThrow();
            redis.opsForValue().set("product:" + id, cached, Duration.ofMinutes(10));
        }
        return cached;
    }
}

